const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/pdf_template_configs',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[record_generic_tool_id]': 'SOME_INTEGER_VALUE',
    'filters[project_id]': 'SOME_INTEGER_VALUE',
    'filters[template_name]': 'SOME_STRING_VALUE',
    'filters[only_parent]': 'SOME_BOOLEAN_VALUE',
    scope: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/pdf_template_configs?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Brecord_generic_tool_id%5D=SOME_INTEGER_VALUE&filters%5Bproject_id%5D=SOME_INTEGER_VALUE&filters%5Btemplate_name%5D=SOME_STRING_VALUE&filters%5Bonly_parent%5D=SOME_BOOLEAN_VALUE&scope=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

